":"Workshop","venue":"Seminar Hall 1","offset_days":-28,"hours":3,"capacity":82,"real":false},{"title":"UI Design Sprint","description":"Figma to polished screens in one sitting.","category":"Workshop","venue":"Seminar Hall 2","offset_days":-188,"hours":3,"capacity":102,"real":false}],"team":[{"name":"Chiranjeevi","position":"President"},{"name":"Likitha","position":"Vice President"}],"announcements":[{"title":"New members welcome every semester","body":"Whether you're into design, code, or bringing ideas to life — there's a place for you in MAD Club. Register on our page and follow @md_club_nhce.","pinned":true}]},{"slug":"robohorizon","pop":1,"events":[{"title":"Line-Follower Robot Workshop","description":"Build and tune a line-follower from kit parts.","category":"Workshop","venue":"Seminar Hall 1","offset_days":-37,"hours":3,"capacity":71,"real":false},{"title":"Industrial Visit: Automation Plant","description":"Visit an automation facility to see industrial robots at work.","category":"Social","venue":"NHCE Campus","offset_days":-117,"hours":3,"capacity":91,"real":false},{"title":"Robo Race","description":"Inter-team race on a timed obstacle track.","category":"Competition","venue":"Seminar Hall 3","offset_days":-197,"hours":3,"capacity":111,"real":false},{"title":"Advanced Robotics Seminar","description":"Kinematics, control and ROS for the curious.","category":"Talk","venue":"Seminar Hall 1","offset_days":20,"hours":3,"capacity":71,"real":false}],"team":[],"announcements":[{"title":"Welcome to RoboHorizon","body":"A commitment to precision, a journey into robotic excellence.","pinned":true}]},{"slug":"stem","pop":1.4,"events":[{"title":"Synapse '25 — Event 1: Rescue the Lost Satellite","description":"An intense, space-themed challenge where participants decode signals, solve clues and collaborate to rescue a lost satellite using logic and STEM skills.","category":"Competition","venue":"NHCE Campus","starts":"2025-09-12T10:00:00+05:30","hours":4,"capacity":120,"regs":118,"budget":12000,"real":true},{"title":"Synapse '25 — Event 2: Mysteries of the Universe","description":"A debate-style event exploring fascinating mysteries of the universe, blending scientific reasoning with imagination and passionate discussion.","category":"Talk","venue":"NHCE Campus","starts":"2025-09-13T10:00:00+05:30","hours":3,"capacity":100,"regs":92,"budget":8000,"real":true},{"title":"Break Out The Code","description":"A problem-solving event testing logical reasoning, teamwork and mathematical aptitude.","category":"Competition","venue":"NHCE Campus","starts":"2025-10-18T10:00:00+05:30","hours":3,"capacity":100,"regs":96,"budget":7000,"real":true},{"title":"E = MC²: Quiz & Innovation Expo","description":"A quiz competition along with an Innovation Expo bringing together innovation, intellect and scientific curiosity.","category":"Competition","venue":"NHCE Campus","starts":"2025-11-22T10:00:00+05:30","hours":5,"capacity":150,"regs":134,"budget":15000,"real":true},{"title":"Mathrubasha Diwas","description":"A vibrant showcase of culture and confidence, where participants display diverse talents across art, science and expression.","category":"Social","venue":"NHCE Campus","starts":"2026-02-21T11:00:00+05:30","hours":3,"capacity":150,"regs":110,"budget":6000,"real":true},{"title":"STEM X Borderland","description":"An immersive event inspired by Alice in Borderland, blending strategic challenges with hands-on STEM learning.","category":"Competition","venue":"NHCE Campus","starts":"2026-03-14T10:00:00+05:30","hours":5,"capacity":120,"regs":120,"budget":14000,"real":true},{"title":"Fresher's Stage","description":"A showcase of creativity and confidence where freshers display diverse talents.","category":"Social","venue":"NHCE Auditorium","starts":"2025-10-04T14:00:00+05:30","hours":3,"capacity":200,"regs":150,"budget":9000,"real":true},{"title":"Builder's Asylum","description":"Signature build challenge: prototype under pressure.","category":"Competition","venue":"Seminar Hall 1","offset_days":-37,"hours":3,"capacity":64,"real":false},{"title":"Traffic 360","description":"Signature event on solving urban traffic problems with tech.","category":"Competition","venue":"Seminar Hall 2","offset_days":-144,"hours":3,"capacity":84,"real":false},{"title":"E-Wasted","description":"Signature event turning e-waste into working builds.","category":"Competition","venue":"Seminar Hall 3","offset_days":-250,"hours":3,"capacity":104,"real":false}],"team":[{"name":"Navaneeth Krishnan","position":"President"},{"name":"M L Pratyusha","position":"Vice President"},{"name":"Sahasra Amineni","position":"Secretary"},{"name":"Mohammed Faidh","position":"Treasurer"},{"name":"Prarthana Krishnamurthy","position":"Program Chair"},{"name":"Kenneth Joshua","position":"Program Vice Chair"},{"name":"Jhanvi Chenji","position":"Project Chair"},{"name":"Kemisetti Hemachandra","position":"Project Vice Chair"},{"name":"Himavarshini M","position":"Marketing Chair"},{"name":"Chintalapati Hasini","position":"Marketing Vice Chair"},{"name":"Sanjay Padmaraj","position":"Review Chair"}],"announcements":[{"title":"Investiture Ceremony 2025-26","body":"Student leaders of all co-curricular clubs for 2025-26 were recognised at the Investiture Ceremony.","pinned":false},{"title":"Welcome to the STEM Club","body":"Learn by doing, network, showcase your talent and build career-ready skills. See All Events for inspiration.","pinned":true}]},{"slug":"tech-forge-club","pop":1.5,"events":[{"title":"A Day of Giving","description":"A day of service at Sparsha Trust, Mathikere — Tech Forge takes its energy off-campus.","category":"Social","venue":"Sparsha Trust, Mathikere","starts":"2023-05-20T10:00:00+05:30","hours":5,"capacity":60,"regs":48,"budget":8000,"real":true},{"title":"Helping Hands","description":"Outreach programme: Tech Forge members step beyond campus to give, teach and uplift the community.","category":"Social","venue":"Community outreach","starts":"2024-05-18T10:00:00+05:30","hours":5,"capacity":80,"regs":72,"budget":12000,"real":true},{"title":"Kratos '24 — NHCE Team","description":"Tech Forge members represent NHCE at the inter-collegiate tech fest Kratos '24.","category":"Competition","venue":"Inter-college fest","starts":"2024-10-12T09:00:00+05:30","hours":8,"capacity":40,"regs":34,"budget":10000,"real":true},{"title":"TECHFORGE '26","description":"The flagship national-level tech fest — hackathons, coding arenas, robotics battles, tech quizzes and keynotes. Code. Innovate. Automate.","category":"Competition","venue":"NHCE Campus","starts":"2026-03-20T09:00:00+05:30","hours":9,"capacity":400,"regs":380,"budget":60000,"real":true},{"title":"Full-Stack Weekend Bootcamp","description":"Weekend deep-dive into full-stack development.","category":"Workshop","venue":"Seminar Hall 1","offset_days":-28,"hours":3,"capacity":75,"real":false},{"title":"Cloud & DevOps Workshop","description":"Deploy an app with CI/CD on a cloud platform.","category":"Workshop","venue":"Seminar Hall 2","offset_days":-135,"hours":3,"capacity":95,"real":false},{"title":"Industry Guest Lecture","description":"Industry engineers decode the technologies of tomorrow.","category":"Talk","venue":"Seminar Hall 3","offset_days":-241,"hours":3,"capacity":115,"real":false}],"team":[{"name":"Priyanka","position":"President"},{"name":"Gauri B Nair","position":"Vice President"},{"name":"Ritisha","position":"Secretary"},{"name":"Ishmita Menon","position":"Treasurer"},{"name":"Abbas","position":"Program Chair"},{"name":"Rohith","position":"Marketing Chair"},{"name":"Prem","position":"Project Chair"},{"name":"Rishima","position":"Review Chair"},{"name":"Prasad","position":"Program Vice Chair"},{"name":"Praneeth","position":"Marketing Vice Chair"},{"name":"Abhay","position":"Project Vice Chair"}],"announcements":[{"title":"Join 200+ builders, breakers and creators","body":"Open to all NHCE students — no experience needed, just bring the fire. DM @techforge_nhce.","pinned":true}]}]$json$;
  c jsonb; e jsonb; m jsonb; a jsonb;
  v_club uuid; v_event uuid; v_start timestamptz; v_end timestamptz; v_cap int; v_regs int; v_budget numeric; v_rate numeric;
  firsts text[] := array['Aarav','Diya','Vihaan','Ananya','Aditya','Isha','Rohan','Meera','Kabir','Saanvi','Arjun','Priya','Karthik','Neha','Rahul','Sneha','Siddharth','Kavya','Varun','Pooja','Harsha','Divya','Nikhil','Aishwarya','Sai','Lakshmi','Manoj','Shreya','Tanvi','Yash','Bhavana','Chetan','Deepika','Ganesh','Ishaan','Jahnavi','Kiran','Madhuri','Naveen','Rhea'];
  lasts  text[] := array['Sharma','Patel','Reddy','Iyer','Nair','Gupta','Singh','Das','Menon','Rao','Kulkarni','Joshi','Mehta','Bose','Pillai','Hegde','Shetty','Gowda','Naidu','Bhat','Kamath','Prasad','Verma','Jain','Khan','Fernandes','Murthy','Acharya','Srinivasan','Krishnan'];
  depts  text[] := array['CSE','ISE','AIML','ECE','EEE','MECH','CIVIL','AI&DS'];
  codes  text[] := array['CS','IS','AI','EC','EE','ME','CV','AD'];
  comments text[] := array['Great session!','Very useful, learned a lot.','Could have been better organised.','Loved the hands-on part.','More such events please.','Speakers were excellent.','A bit rushed but fun.','Well run and on time.'];
begin
  for c in select * from jsonb_array_elements(spec) loop
    select id into v_club from public.clubs where slug = c->>'slug';
    if v_club is null then
      raise notice 'Club % not found — run seed_real_clubs.sql first', c->>'slug';
      continue;
    end if;

    -- events
    for e in select * from jsonb_array_elements(c->'events') loop
      delete from public.events where club_id = v_club and title = e->>'title';
      v_start := coalesce((e->>'starts')::timestamptz, date_trunc('hour', now()) + ((e->>'offset_days')::int || ' days')::interval + interval '10 hours');
      v_end := v_start + ((e->>'hours')::numeric || ' hours')::interval;
      v_cap := (e->>'capacity')::int;
      v_regs := coalesce((e->>'regs')::int, floor(v_cap * (0.5 + random() * 0.5) * least((c->>'pop')::numeric, 1.2))::int);
      v_budget := coalesce((e->>'budget')::numeric, 2000 + floor(random() * 6000));
      insert into public.events (club_id, title, description, category, venue, starts_at, ends_at, capacity, budget_allocated, budget_spent, status, registration_open)
      values (v_club, e->>'title', e->>'description', e->>'category', e->>'venue', v_start, v_end, v_cap,
              v_budget, case when v_start < now() then round(v_budget * (0.6 + random() * 0.4)) else 0 end, 'published', true)
      returning id into v_event;

      -- sign-ups (the capacity trigger confirms or waitlists them, exactly like real sign-ups)
      insert into public.event_registrations (event_id, full_name, email, roll_no, department, year, phone, registered_at)
      select v_event, p.fn || ' ' || p.ln,
             lower(p.fn || '.' || p.ln || p.g || '@students.nhce.example'),
             '1NH' || lpad((26 - p.yr)::text, 2, '0') || codes[p.d] || lpad((1 + floor(random() * 180))::int::text, 3, '0'),
             depts[p.d], p.yr,
             (array['98','97','99','90','81','63'])[1 + floor(random() * 6)::int] || lpad((floor(random() * 99999999))::bigint::text, 8, '0'),
             least(v_start - interval '2 hours', now()) - random() * interval '14 days'
      from (
        select g,
               firsts[1 + floor(random() * array_length(firsts, 1))::int] as fn,
               lasts[1 + floor(random() * array_length(lasts, 1))::int] as ln,
               1 + floor(random() * 8)::int as d,
               1 + floor(random() * 4)::int as yr
        from generate_series(1, v_regs) g
      ) p
      on conflict do nothing;

      if v_start < now() then
        -- attendance (inserts always start unattended), then feedback from some of those who came
        v_rate := 0.62 + random() * 0.25;
        update public.event_registrations
           set attended = true, attended_at = v_start + random() * interval '40 minutes'
         where event_id = v_event and status = 'confirmed' and random() < v_rate;
        insert into public.event_feedback (event_id, full_name, email, rating, comment)
        select v_event, r.full_name, r.email,
               greatest(1, least(5, round(3.3 + random() * 1.9 + ((c->>'pop')::numeric - 1) * 0.5)::int)),
               case when random() < 0.7 then comments[1 + floor(random() * array_length(comments, 1))::int] end
        from public.event_registrations r
        where r.event_id = v_event and r.attended and random() < 0.55;
      end if;
    end loop;

    -- roster: the real student council (as listed on the club site) plus simulated general members
    delete from public.club_members
     where club_id = v_club
       and (email like '%@students.nhce.example'
            or full_name in (select t->>'name' from jsonb_array_elements(c->'team') t));
    for m in select * from jsonb_array_elements(c->'team') loop
      insert into public.club_members (club_id, full_name, position, status, joined_on)
      values (v_club, m->>'name', m->>'position', 'active', current_date - (200 + floor(random() * 300))::int);
    end loop;
    insert into public.club_members (club_id, full_name, email, roll_no, department, year, position, status, joined_on)
    select v_club, p.fn || ' ' || p.ln, lower(p.fn || '.' || p.ln || p.g || '@students.nhce.example'),
           '1NH' || lpad((26 - p.yr)::text, 2, '0') || codes[p.d] || lpad((1 + floor(random() * 180))::int::text, 3, '0'),
           depts[p.d], p.yr, 'Member', case when random() < 0.12 then 'alumni' else 'active' end,
           current_date - (random() * 700)::int
    from (
      select g,
             firsts[1 + floor(random() * array_length(firsts, 1))::int] as fn,
             lasts[1 + floor(random() * array_length(lasts, 1))::int] as ln,
             1 + floor(random() * 8)::int as d,
             1 + floor(random() * 4)::int as yr
      from generate_series(1, floor((18 + random() * 22) * (c->>'pop')::numeric)::int) g
    ) p;

    -- announcements
    for a in select * from jsonb_array_elements(c->'announcements') loop
      delete from public.announcements where club_id = v_club and title = a->>'title';
      insert into public.announcements (club_id, title, body, pinned)
      values (v_club, a->>'title', a->>'body', coalesce((a->>'pinned')::boolean, false));
    end loop;
  end loop;
end $seed$;
